css += r'''

/* Servis Oturma — eski editör paritesi v2 */
.ka-bus-classic-modal{width:min(660px,100%);max-height:calc(100dvh - 18px);padding:0;overflow:hidden;background:color-mix(in srgb,var(--ka-card-bg) 94%,var(--ka-primary) 6%);border-color:color-mix(in srgb,var(--ka-primary) 30%,var(--ka-border));border-radius:20px}.ka-bus-classic-header{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:18px 22px;background:linear-gradient(110deg,#0d6a4c,#20866c);color:#fff}.ka-bus-classic-header h2{color:#fff;font-size:clamp(19px,5vw,27px)}.ka-bus-classic-header .ka-icon-button{color:#fff;background:rgba(255,255,255,.1)}.ka-bus-classic-content{padding:18px 20px 22px;overflow-y:auto;overscroll-behavior:contain}.ka-bus-classic-hero{padding:20px;border:1px solid var(--ka-border);border-radius:22px;background:var(--ka-card-bg);box-shadow:var(--ka-shadow-sm)}.ka-bus-classic-hero h3{margin-bottom:18px;font-size:21px}.ka-bus-classic-stats{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}.ka-bus-classic-stats div:last-child{grid-column:1/-1}.ka-bus-classic-stats small{display:block;margin-bottom:4px;color:var(--ka-text-muted);font-size:12px;letter-spacing:.02em}.ka-bus-classic-stats strong{display:block;font-size:clamp(18px,4.8vw,25px);line-height:1.35}.ka-bus-classic-hero p{margin-top:18px;padding-top:14px;border-top:1px dashed var(--ka-border);color:var(--ka-text-muted)}.ka-bus-template-section{display:grid;gap:10px;margin-top:18px}.ka-bus-template-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.ka-bus-template-card{min-height:80px;display:grid;grid-template-columns:auto 1fr;grid-template-rows:auto auto;align-items:center;column-gap:9px;padding:12px 14px;border:1px solid var(--ka-border);border-radius:16px;background:var(--ka-card-bg);color:var(--ka-text);text-align:left;cursor:pointer}.ka-bus-template-card>span{grid-row:1/3;font-size:22px}.ka-bus-template-card strong{font-size:15px}.ka-bus-template-card small{color:var(--ka-text-muted);line-height:1.25}.ka-bus-template-card.is-active{background:var(--ka-primary);border-color:var(--ka-primary);color:var(--ka-text-inverse);box-shadow:0 8px 22px color-mix(in srgb,var(--ka-primary) 24%,transparent)}.ka-bus-template-card.is-active small{color:color-mix(in srgb,var(--ka-text-inverse) 75%,transparent)}.ka-bus-template-card:disabled{opacity:.55;cursor:not-allowed}.ka-bus-template-card:last-child:nth-child(odd){grid-column:1/-1}.ka-bus-edit-row{display:flex;justify-content:flex-end;margin:14px 0 2px}.ka-bus-edit-hint{padding:10px 12px;border:1px solid color-mix(in srgb,var(--ka-warning) 36%,var(--ka-border));border-radius:12px;background:color-mix(in srgb,var(--ka-warning) 10%,var(--ka-card-bg));color:var(--ka-text-muted);font-size:13px}.ka-bus-classic-stage{display:flex;justify-content:center;margin-top:10px;overflow-x:auto;padding:6px 0 2px}.ka-bus-cabin.ka-bus-classic-shell{position:relative;width:min(410px,100%);min-height:560px;display:block;padding:26px 16px 18px;border:3px solid color-mix(in srgb,var(--ka-text-muted) 48%,transparent);border-radius:46px 46px 22px 22px;background:color-mix(in srgb,var(--ka-card-bg) 70%,#546274 30%);box-shadow:inset 0 -12px 0 rgba(0,0,0,.12),0 18px 34px rgba(0,0,0,.16)}.ka-bus-classic-lights{display:grid;grid-template-columns:34px 1fr 34px;gap:12px;align-items:center;margin:-9px 0 10px}.ka-bus-classic-lights span{text-align:center;font-size:23px}.ka-bus-classic-lights i{height:28px;border-radius:8px;background:linear-gradient(#275986,#193c5c);border:1px solid rgba(255,255,255,.14)}.ka-bus-classic-plate{width:max-content;max-width:82%;margin:0 auto 14px;padding:5px 12px;border:2px solid #74818c;border-radius:10px;background:#182126;color:#f8fafc;font:800 16px/1 var(--ka-font-mono);letter-spacing:.12em;white-space:nowrap}.ka-bus-classic-front-row{display:grid;grid-template-columns:minmax(120px,1.18fr) minmax(130px,1fr);gap:18px;align-items:start;margin-bottom:10px}.ka-bus-classic-driver{min-height:82px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:4px;padding:8px;border:1px solid color-mix(in srgb,var(--ka-warning) 40%,var(--ka-border));border-radius:18px;background:color-mix(in srgb,var(--ka-warning) 13%,var(--ka-card-bg));color:color-mix(in srgb,var(--ka-warning) 72%,var(--ka-text));text-align:center}.ka-bus-classic-driver span{font-size:34px}.ka-bus-classic-driver strong{max-width:100%;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.ka-bus-classic-front-seats{display:flex;gap:8px;justify-content:flex-end}.ka-bus-classic-body{display:grid;gap:8px;padding-top:4px}.ka-bus-classic-row{width:100%;display:grid!important;grid-template-columns:1fr 42px 1fr!important;gap:8px!important;align-items:center}.ka-bus-classic-side{display:flex;gap:8px;min-height:68px}.ka-bus-classic-side.is-left{justify-content:flex-end}.ka-bus-classic-side.is-right{justify-content:flex-start}.ka-bus-classic-aisle{height:100%;min-height:68px;display:flex;align-items:center;justify-content:center;border-inline:1px dashed rgba(255,255,255,.12)}.ka-bus-classic-door{display:flex;flex-direction:column;gap:2px;align-items:center;color:#9a5a31;font-size:18px}.ka-bus-classic-door b{font-size:8px;letter-spacing:.12em;color:var(--ka-text-muted);writing-mode:vertical-rl}.ka-bus-classic-shell .ka-bus-seat{position:relative;flex:0 0 clamp(56px,16vw,70px);width:clamp(56px,16vw,70px);height:68px;min-height:68px;padding:9px 5px 5px;border:2px solid #536072;border-radius:17px;background:#3c4658;color:#dbe4ee;box-shadow:inset -6px -5px 0 rgba(255,255,255,.06);overflow:hidden}.ka-bus-classic-shell button.ka-bus-seat{cursor:pointer}.ka-bus-classic-shell .ka-bus-seat.is-filled{background:#20c666;border-color:#12a653;color:#fff;box-shadow:inset -6px -5px 0 rgba(0,0,0,.12),0 4px 9px rgba(16,185,90,.2)}.ka-bus-classic-shell .ka-bus-seat.is-reserved{background:#327de2;border-color:#2367c1;color:#fff}.ka-bus-classic-shell .ka-bus-seat.is-locked{background:#f59e0b;border-color:#d88100;color:#241700}.ka-bus-classic-shell .ka-bus-seat__number{position:absolute;top:4px;left:6px;font-size:10px;font-weight:850;opacity:.88}.ka-bus-classic-shell .ka-bus-seat__lock{position:absolute;top:3px;right:4px;font-size:10px}.ka-bus-classic-shell .ka-bus-seat__avatar{width:27px;height:27px;margin:1px auto 2px;border-radius:50%;display:grid;place-items:center;background:rgba(255,255,255,.26);font-size:12px;font-weight:900}.ka-bus-classic-shell .ka-bus-seat__name{display:block;width:100%;font-size:11px;font-weight:850;line-height:1.05;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;text-align:center}.ka-bus-classic-rear{display:flex;gap:7px;justify-content:center;margin-top:14px;padding-top:14px;border-top:1px dashed rgba(255,255,255,.18)}.ka-bus-classic-rear .ka-bus-seat{flex:1 1 0;max-width:76px}.ka-bus-row-actions{display:flex;justify-content:center;gap:12px;margin:14px 0}.ka-bus-classic-legend{width:max-content;max-width:100%;margin:14px auto 0;padding:10px 14px;border:1px solid var(--ka-border);border-radius:999px;background:var(--ka-card-bg);display:flex;flex-wrap:wrap;justify-content:center;gap:12px}.ka-bus-classic-legend span{display:inline-flex;align-items:center;gap:6px}.ka-bus-classic-legend i{width:17px;height:17px;border-radius:5px;border:1px solid transparent}.ka-bus-classic-legend i.is-filled{background:#20c666;border-color:#12a653}.ka-bus-classic-legend i.is-empty{background:#3c4658;border-color:#536072}.ka-bus-classic-legend i.is-reserved{background:#327de2;border-color:#2367c1}.ka-bus-classic-legend i.is-locked{background:#f59e0b;border-color:#d88100}.ka-bus-classic-actions{display:grid;grid-template-columns:1fr;gap:10px;margin-top:12px}.ka-bus-classic-actions .ka-btn{width:100%}.ka-bus-classic-footer{display:grid;grid-template-columns:1fr 1fr;gap:14px;padding:16px 20px max(16px,var(--ka-safe-bottom));background:var(--ka-card-bg);border-top:1px solid var(--ka-border)}.ka-bus-classic-footer .ka-btn{min-height:54px;font-size:17px}.ka-bus-seat-picker{z-index:1325!important}.ka-bus-seat-picker__modal{width:min(560px,calc(100% - 18px));max-height:calc(100dvh - 24px)}.ka-bus-seat-picker-actions{display:grid;grid-template-columns:repeat(2,1fr);gap:8px}.ka-bus-student-list{display:grid;gap:8px;max-height:min(54dvh,440px);overflow:auto}.ka-bus-student-option{width:100%;display:flex;align-items:center;gap:10px;padding:10px;border:1px solid var(--ka-border);border-radius:13px;background:var(--ka-card-bg);color:var(--ka-text);text-align:left}.ka-bus-student-option__avatar{width:38px;height:38px;flex:0 0 38px;border-radius:50%;display:grid;place-items:center;background:var(--ka-primary-soft);color:var(--ka-primary);font-weight:850}.ka-bus-student-option small{display:block;color:var(--ka-text-muted);margin-top:2px}.ka-bus-editor-backdrop{z-index:1250;padding:9px}.ka-bus-editor-modal{overflow:hidden}.ka-bus-editor-modal>.ka-modal__body{min-height:0}.ka-bus-editor-modal>.ka-modal__footer{flex:0 0 auto}
@media(max-width:560px){.ka-bus-classic-header{padding:15px 16px}.ka-bus-classic-header h2{font-size:20px}.ka-bus-classic-content{padding:14px 12px 18px}.ka-bus-classic-hero{padding:16px}.ka-bus-classic-stats{gap:12px}.ka-bus-template-card{min-height:74px;padding:10px}.ka-bus-classic-shell{min-width:340px!important}.ka-bus-classic-stage{justify-content:flex-start}.ka-bus-classic-shell .ka-bus-seat{flex-basis:61px;width:61px;height:64px;min-height:64px}.ka-bus-classic-row{grid-template-columns:1fr 34px 1fr!important;gap:6px!important}.ka-bus-classic-side{gap:6px}.ka-bus-classic-front-row{gap:10px}.ka-bus-classic-front-seats{gap:6px}.ka-bus-classic-footer{padding-inline:12px}.ka-bus-seat-picker-actions{grid-template-columns:1fr 1fr}}
@media(max-width:390px){.ka-bus-template-grid{grid-template-columns:1fr}.ka-bus-template-card:last-child:nth-child(odd){grid-column:auto}.ka-bus-classic-stats{grid-template-columns:1fr 1fr}.ka-bus-classic-stats div:last-child{grid-column:auto}.ka-bus-classic-footer{gap:8px}.ka-bus-classic-footer .ka-btn{padding-inline:8px}.ka-bus-classic-shell{transform-origin:top left}}
'''
css_path.write_text(css,encoding='utf-8')

# Stronger parity contract for the screenshot-era editor while retaining local-first boundaries.
test_path=Path('tests/transport-seating-visual-editor.test.js')
test_path.write_text(r'''const fs=require('fs');
const assert=require('assert');
const transport=fs.readFileSync('js/modules/transport.js','utf8');
const design=fs.readFileSync('css/design-system.css','utf8');
new Function(transport);
for(const token of ['ka-bus-classic-shell','data-bus-seat-index','function openBusSeatPicker','data-bus-student','function assignBusStudent','data-bus-template','data-bus-layout-edit','Düzenlemeyi Aç','data-bus-row-add','Sıra Ekle','data-bus-row-remove','Sıra Sil','data-bus-seat-lock','Kilitli','data-bus-clear-all','Atamaları Temizle','data-bus-report','Rapor Al','Vazgeç','💾 Kaydet','function busPrintReport','ReportEngine.printReport'])assert(transport.includes(token),`Klasik servis oturma editörü paritesi eksik: ${token}`);
for(const token of ['.ka-bus-classic-modal','.ka-bus-classic-hero','.ka-bus-template-grid','.ka-bus-template-card','.ka-bus-classic-shell','.ka-bus-classic-driver','.ka-bus-classic-row','.ka-bus-seat.is-filled','.ka-bus-seat.is-reserved','.ka-bus-seat.is-locked','.ka-bus-classic-footer','.ka-bus-seat-picker'])assert(design.includes(token),`Merkezi klasik servis oturma stili eksik: ${token}`);
assert(!transport.includes('data-seat-index'),'Servis oturma planı koltuk başına dropdown kartlara geri dönmemeli.');
assert(!transport.includes('id="busTemplateSelect"'),'Araç seçimi eski ekrandaki kartlı şablon seçicisi olmalı.');
assert(transport.includes('editor={servisId,sablon,elements,editable:canEditBusSeats()}'),'Canonical editör state/permission sözleşmesi korunmalı.');
assert(transport.includes('window.ServisOturmaService.planElementsKaydet(editor.servisId,editor.sablon,editor.elements,false)'),'Kayıt local-first canonical servis üzerinden yapılmalı.');
assert(transport.includes("if(!editor?.editable)return"),'Öğretmen salt-okunur davranışı korunmalı.');
for(const forbidden of ['db.collection','firebase.firestore','localStorage.setItem','localStorage.removeItem'])assert(!transport.includes(forbidden),`Servis oturma editörü yasaklı kalıcı katmana inmemeli: ${forbidden}`);
console.log('Klasik görsel servis oturma editörü parite kilidi başarılı.');
''',encoding='utf-8')

index=Path('index.html')
ix=index.read_text(encoding='utf-8')
if 'css/design-system.css?v=881' not in ix: raise SystemExit('index css cache token changed')
index.write_text(ix.replace('css/design-system.css?v=881','css/design-system.css?v=889'),encoding='utf-8')

sw_path=Path('service-worker.js')
sw=sw_path.read_text(encoding='utf-8')
if "oy-cache-v888" not in sw: raise SystemExit('service worker cache token changed')
sw=sw.replace("oy-cache-v888","oy-cache-v889").replace("./css/design-system.css?v=881","./css/design-system.css?v=889")
sw_path.write_text(sw,encoding='utf-8')
